import static bootcamp.Check.*;

import java.util.*;
import java.util.stream.*;

class Exercise {

    record Badge(String id) {}

    record Scan(String badgeId, int at) {}

    /** Distinct badges (records compare by value). */
    static int uniqueBadges(List<Badge> xs) {
        return (int) xs.stream().distinct().count();
    }

    /** Distinct arrays by contents. */
    static int uniqueDigitArrays(List<int[]> xs) {
        return (int) xs.stream().map(a -> Arrays.stream(a).boxed().toList()).distinct().count();
