    /** The first scan of each badge, in the order the scans arrived. */
    static List<Scan> firstScanPerBadge(List<Scan> scans) {
        var seen = new HashSet<String>();
        return scans.stream().filter(s -> seen.add(s.badgeId())).toList();
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("records deduplicate by value", () ->
            eq(uniqueBadges(List.of(new Badge("a"), new Badge("b"), new Badge("a"))), 2));
        test("boxed contents deduplicate by value, raw arrays by identity", () -> {
            eq(uniqueDigitArrays(List.of(new int[] {1, 2}, new int[] {1, 2})), 1);
            eq(Stream.of(new int[] {1, 2}, new int[] {1, 2}).distinct().count(), 2);
