// ─────────────────────────────────────────────────────────────────────────
//  08 · splicing streams together                                    ★★☆
//  concepts: Stream.flatMap · nested flatMap cross product · encounter order
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.stream.*;

class Exercise {

    /** Every tag of every group, in order. */
    static List<String> allTags(List<List<String>> groups) {
        return groups.stream().flatMap(List::stream).toList();
    }

    /** a-b for every a, then every b. */
    static List<String> pairs(List<String> as, List<String> bs) {
        return as.stream().flatMap(a -> bs.stream().map(b -> a + "-" + b)).toList();
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("allTags splices groups in order and an empty group vanishes (boundary)", () ->
            eq(allTags(List.of(List.of("a", "b"), List.of(), List.of("c"))), List.of("a", "b", "c")));
        test("pairs is the cross product in encounter order", () ->
            eq(pairs(List.of("x", "y"), List.of("1", "2")), List.of("x-1", "x-2", "y-1", "y-2")));
        test("pairs with an empty side is empty", () -> {
            eq(pairs(List.of(), List.of("1", "2")), List.of());
            eq(pairs(List.of("x"), List.of()), List.of());
        });
        test("no groups at all is empty", () ->
            eq(allTags(List.of()), List.of()));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}
